#include <cstdio>
#include <vector>
#include <queue>
#include <cstring>
#define MAXN 256
#define INF 1000000000
using namespace std;
struct Edge {
	int u, v, flow, cap, next;
	Edge() {}
	Edge(int u, int v, int flow, int cap, int next): u(u), v(v), flow(flow), cap(cap), next(next) {}
};
class Dinic {
public:
	vector<Edge> edges;
	int n, s, t, head[MAXN], current[MAXN], dist[MAXN];
	void init(int n, int s, int t) {
		this->n = n;
		this->s = s;
		this->t = t;
		edges.clear();
		memset(head, -1, sizeof(int) * n);
	}
	void addEdge(int u, int v, int cap) {
		edges.emplace_back(u, v, 0, cap, head[u]);
		head[u] = (int)edges.size() - 1;
		edges.emplace_back(v, u, 0, 0, head[v]);
		head[v] = (int)edges.size() - 1;
	}
	bool bfs() {
		memset(dist, -1, sizeof(int) * n);
		queue<int> q;
		q.push(s);
		dist[s] = 0;
		while(!q.empty()) {
			int u = q.front(); q.pop();
			for(int i = head[u]; i != -1; i = edges[i].next) {
				if(edges[i].flow < edges[i].cap && dist[edges[i].v] == -1) {
					dist[edges[i].v] = dist[u] + 1;
					q.push(edges[i].v);
				}
			}
		}
		return dist[t] != -1;
	}
	int sendFlow(int u, int flow) {
		if(u == t)
			return flow;
		for(int& i = current[u]; i != -1; i = edges[i].next) {
			if(edges[i].flow < edges[i].cap && dist[edges[i].v] == dist[u] + 1) {
				int curr_flow = min(flow, edges[i].cap - edges[i].flow);
				int temp_flow = sendFlow(edges[i].v, curr_flow);
				if(temp_flow > 0) {
					edges[i].flow += temp_flow;
					edges[i ^ 1].flow -= temp_flow;
					return temp_flow;
				}
			}
		}
		return 0;
	}
	int maxFlow() {
		int total = 0;
		while(bfs()) {
			for(int i = 0; i < n; ++i)
				current[i] = head[i];
			while(int flow = sendFlow(s, INF))
				total += flow;
		}
		return total;
	}
};
int n, t, zx, zy;
char smp[12][12], cmp[12][12], work[12][12];
int vis[12][12];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, -1, 0, 1};
inline int X(int i, int j) { return i * n + j; }
inline int Y(int i, int j) { return n * n + i * n + j; }
inline int S() { return n * n * 2; }
inline int T() { return S() + 1; }
inline int N() { return T() + 1; }
struct Node {
	int x, y, t, type;
	Node() {}
	Node(int x, int y, int t, int type): x(x), y(y), t(t), type(type) {}
};
void bfs(int sx, int sy) {
	queue<Node> q;
	q.push(Node(sx, sy, 0, 0));
	vis[sx][sy] = 1;
	q.push(Node(zx, zy, 0, 1));
	while(!q.empty()) {
		Node u = q.front(); q.pop();
		int nx, ny;
		if(u.t == t)
			break;
		if(u.type == 0 && isalpha(work[u.x][u.y]))
			continue;
		for(int i = 0; i < 4; ++i) {
			nx = u.x + dx[i];
			ny = u.y + dy[i];
			if(nx >= 0 && nx < n && ny >= 0 && ny < n) {
				if(u.type == 0 && !vis[nx][ny] && !isalpha(work[nx][ny])) {
					vis[nx][ny] = 1;
					q.push(Node(nx, ny, u.t + 1, 0));
				}
				else if(u.type == 1 && !isalpha(work[nx][ny])) {
					work[nx][ny] = 'Z';
					q.push(Node(nx, ny, u.t + 1, 1));
				}
			}
		}
	}
}
int main() {
	while(scanf("%d%d", &n, &t) != EOF) {
		Dinic dinic;
		dinic.init(N(), S(), T());
		for(int i = 0; i < n; ++i) {
			scanf("%s", smp[i]);
			for(int j = 0; j < n; ++j)
				if(isdigit(smp[i][j]) && smp[i][j] > '0')
					dinic.addEdge(S(), X(i, j), smp[i][j] - '0');
				else if(smp[i][j] == 'Z') {
					zx = i;
					zy = j;
				}
		}
		for(int i = 0; i < n; ++i) {
			scanf("%s", cmp[i]);
			for(int j = 0; j < n; ++j)
				if(isdigit(cmp[i][j]) && cmp[i][j] > '0')
					dinic.addEdge(Y(i, j), T(), cmp[i][j] - '0');
		}
		for(int i = 0; i < n; ++i)
			for(int j = 0; j < n; ++j) {
				if(!isdigit(smp[i][j]) || smp[i][j] <= '0')
					continue;
				memset(vis, 0, sizeof(vis));
				memcpy(work, smp, sizeof(smp));
				bfs(i, j);
				for(int xi = 0; xi < n; ++xi)
					for(int yi = 0; yi < n; ++yi) {
						if(!isdigit(cmp[xi][yi]) || cmp[xi][yi] <= '0')
							continue;
						if(vis[xi][yi]) {
							dinic.addEdge(X(i, j), Y(xi, yi), INF);
						}
					}
			}
		printf("%d\n", dinic.maxFlow());
	}
	return 0;
}
